import os, pty, time, select

def run(bin_path):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp("zsh", ["zsh", "-f", "-i"])
        os._exit(127)
    def send(s): os.write(fd, s.encode())
    def drain(t):
        end=time.time()+t; buf=b""
        while time.time()<end:
