    send("\x03")                    # Ctrl-C -> SIGINT to the foreground child
    time.sleep(1.5)
    send("echo BROKE_OUT_MARKER\n") # only echoes if we're back at the prompt
    out = drain(1.5)
    try: send("exit\n"); os.close(fd)
    except OSError: pass
    try: os.waitpid(pid,0)
    except OSError: pass
    return b"BROKE_OUT_MARKER" in out, out.count(b"ITER_DONE")

